2708	// Primary pass pipeline description parsing routine for a \c ModulePassManager
2709	// FIXME: Should this routine accept a TargetMachine or require the caller to
2710	// pre-populate the analysis managers with target-specific stuff?
2711	Error PassBuilder::parsePassPipeline(ModulePassManager &MPM,
2712	                                     StringRef PipelineText) {
2713	  auto Pipeline = parsePipelineText(PipelineText);
2714	  if (!Pipeline || Pipeline->empty())
2715	    return make_error<StringError>(
2716	        formatv("invalid pipeline '{}'", PipelineText).str(),
2717	        inconvertibleErrorCode());
2718	
2719	  // If the first name isn't at the module layer, wrap the pipeline up
2720	  // automatically.
2721	  StringRef FirstName = Pipeline->front().Name;
2722	
2723	  if (!isModulePassName(FirstName, ModulePipelineParsingCallbacks)) {
2724	    bool UseMemorySSA;
2725	    if (isCGSCCPassName(FirstName, CGSCCPipelineParsingCallbacks)) {
2726	      Pipeline = {{"cgscc", std::move(*Pipeline)}};
2727	    } else if (isFunctionPassName(FirstName,
2728	                                  FunctionPipelineParsingCallbacks)) {
2729	      Pipeline = {{"function", std::move(*Pipeline)}};
2730	    } else if (isLoopNestPassName(FirstName, LoopPipelineParsingCallbacks,
2731	                                  UseMemorySSA)) {
2732	      Pipeline = {{"function", {{UseMemorySSA ? "loop-mssa" : "loop",
2733	                                 std::move(*Pipeline)}}}};
2734	    } else if (isLoopPassName(FirstName, LoopPipelineParsingCallbacks,
2735	                              UseMemorySSA)) {
2736	      Pipeline = {{"function", {{UseMemorySSA ? "loop-mssa" : "loop",
2737	                                 std::move(*Pipeline)}}}};
2738	    } else if (isMachineFunctionPassName(
2739	                   FirstName, MachineFunctionPipelineParsingCallbacks)) {
2740	      Pipeline = {{"function", {{"machine-function", std::move(*Pipeline)}}}};
2741	    } else {
2742	      for (auto &C : TopLevelPipelineParsingCallbacks)
2743	        if (C(MPM, *Pipeline))
2744	          return Error::success();
2745	
2746	      // Unknown pass or pipeline name!
2747	      auto &InnerPipeline = Pipeline->front().InnerPipeline;
2748	      return make_error<StringError>(
2749	          formatv("unknown {} name '{}'",
2750	                  (InnerPipeline.empty() ? "pass" : "pipeline"), FirstName)
2751	              .str(),
2752	          inconvertibleErrorCode());
2753	    }
2754	  }
2755	
2756	  if (auto Err = parseModulePassPipeline(MPM, *Pipeline))
2757	    return Err;
2758	  return Error::success();
2759	}
