2761	// Primary pass pipeline description parsing routine for a \c CGSCCPassManager
2762	Error PassBuilder::parsePassPipeline(CGSCCPassManager &CGPM,
2763	                                     StringRef PipelineText) {
2764	  auto Pipeline = parsePipelineText(PipelineText);
2765	  if (!Pipeline || Pipeline->empty())
2766	    return make_error<StringError>(
2767	        formatv("invalid pipeline '{}'", PipelineText).str(),
2768	        inconvertibleErrorCode());
2769	
2770	  StringRef FirstName = Pipeline->front().Name;
2771	  if (!isCGSCCPassName(FirstName, CGSCCPipelineParsingCallbacks))
2772	    return make_error<StringError>(
2773	        formatv("unknown cgscc pass '{}' in pipeline '{}'", FirstName,
2774	                PipelineText)
2775	            .str(),
2776	        inconvertibleErrorCode());
2777	
2778	  if (auto Err = parseCGSCCPassPipeline(CGPM, *Pipeline))
2779	    return Err;
2780	  return Error::success();
2781	}
